'use server';

import { updateTag } from 'next/cache';
import { redirect } from 'next/navigation';
import { createPostInStore } from '../lib/posts';

export async function createPost(formData: FormData) {
  const title = formData.get('title');
  const content = formData.get('content');

  if (typeof title !== 'string' || typeof content !== 'string') {
    throw new Error('Title and content are required');
  }

  const trimmedTitle = title.trim();
  const trimmedContent = content.trim();

  if (!trimmedTitle || !trimmedContent) {
    throw new Error('Title and content cannot be empty');
  }

  createPostInStore(trimmedTitle, trimmedContent);

  // Invalidate the "posts" cache tag so the next page load fetches fresh data.
  // updateTag immediately expires cached data - the next request will wait for
  // fresh data rather than serving stale content (read-your-own-writes).
  updateTag('posts');

  redirect('/');
}

